function insertionSort() {
  markSortedPrefix(1);

  for (let j = 2; j <= n(); j++) {
    let i = j;
    markKey(i);
    note("Insert A[" + j + "] into the sorted prefix.");

    while (i > 1 && compare(i - 1, i)) {
      i = shift(i);
      markKey(i);
    }

    markSortedPrefix(j);
  }

  note("The entire array is sorted.");
}

